#!/usr/bin/env python3
"""PubMed v2 incremental analysis — adapted from WikiText analyze_incremental.py.

Two-level metric hierarchy:
  Level 1 (PRIMARY): Cross-fraction Spearman rho
  Level 2 (AUXILIARY): Cross-generation metrics (delta, max_deviation, AUC, monotonicity_rho)

Usage:
  python analyze_pubmed_incremental.py --data-dir /root/autodl-tmp/collapse_severity_monitor --seeds 42
  python analyze_pubmed_incremental.py --data-dir /path --seeds 42 --compare-wikitext /path/to/wikitext_v2.json
"""

import argparse
import json
import os
import sys
from collections import defaultdict

import numpy as np
from scipy import stats


SUMMARY_SIGNALS = [
    "perplexity", "hellaswag_accuracy",
    "final_stable_rank", "final_spectral_entropy",
    "final_token_entropy", "final_gradient_norm",
]

SIGMA_SIGNALS = [
    "sigma_effective_rank", "sigma_condition_number",
    "sigma_track_ii", "sigma_track_nn",
]

DISPLAY_NAMES = {
    "final_stable_rank": "stable_rank",
    "final_spectral_entropy": "spectral_entropy",
    "final_token_entropy": "token_entropy",
    "final_gradient_norm": "gradient_norm",
}

NOVELTY_MAP = {
    "training_loss": "baseline",
}


def get_novelty(sig_display_name):
    return NOVELTY_MAP.get(sig_display_name, "proposed")


def output_dir_pattern(base_dir):
    return os.path.join(base_dir, "outputs_qwen15b_seed{seed}_pubmed")


def load_summary(base_dir, seed, frac_label):
    path = os.path.join(output_dir_pattern(base_dir).format(seed=seed),
                        f"summary_{frac_label}pct.json")
    if not os.path.exists(path):
        return None
    with open(path) as f:
        return json.load(f)


def load_training_loss(base_dir, seed, frac_label, gen):
    path = os.path.join(output_dir_pattern(base_dir).format(seed=seed),
                        f"signals_{frac_label}pct_gen{gen}.jsonl")
    if not os.path.exists(path):
        return None
    last_signal = None
    with open(path) as f:
        for line in f:
            row = json.loads(line)
            if row.get("generation_end"):
                break
            last_signal = row
    return last_signal.get("training_loss") if last_signal else None


def discover_fractions(base_dir, seeds):
    fracs = set()
    for seed in seeds:
        d = output_dir_pattern(base_dir).format(seed=seed)
        if not os.path.isdir(d):
            continue
        for fn in os.listdir(d):
            if fn.startswith("summary_") and fn.endswith("pct.json"):
                frac_label = fn.replace("summary_", "").replace("pct.json", "")
                fracs.add(frac_label)
    return sorted(fracs, key=lambda x: float(x))


def build_data_table(base_dir, seeds, fracs):
    table = {}
    for seed in seeds:
        for frac_label in fracs:
            summary = load_summary(base_dir, seed, frac_label)
            if summary is None:
                continue
            for entry in summary:
                gen = entry["generation"]
                key = (seed, frac_label, gen)
                row = {}
                for sig in SUMMARY_SIGNALS + SIGMA_SIGNALS:
                    if sig in entry:
                        row[sig] = entry[sig]
                loss = load_training_loss(base_dir, seed, frac_label, gen)
                if loss is not None:
                    row["training_loss"] = loss
                table[key] = row
    return table


def available_signals(table):
    all_sigs = set()
    for row in table.values():
        all_sigs.update(row.keys())
    ordered = []
    for s in SUMMARY_SIGNALS + ["training_loss"] + SIGMA_SIGNALS:
        if s in all_sigs:
            ordered.append(s)
    return ordered


def sig_name(s):
    return DISPLAY_NAMES.get(s, s)


def cross_generation_analysis(table, seeds, fracs, signals):
    results = {}
    for frac_label in fracs:
        frac_results = {}
        for sig in signals:
            seed_metrics = []
            for seed in seeds:
                gens = []
                vals = []
                for gen in range(10):
                    key = (seed, frac_label, gen)
                    if key in table and sig in table[key]:
                        gens.append(gen)
                        vals.append(table[key][sig])
                if len(gens) < 2:
                    continue

                v0 = vals[0]
                vN = vals[-1]
                delta = vN - v0

                deviations = [abs(v - v0) for v in vals]
                max_dev_val = max(deviations)
                max_dev_gen = gens[deviations.index(max_dev_val)]

                auc = 0.0
                for k in range(len(vals) - 1):
                    auc += (abs(vals[k] - v0) + abs(vals[k+1] - v0)) / 2.0

                rho, p_val = (np.nan, np.nan)
                if len(gens) >= 3:
                    rho, p_val = stats.spearmanr(gens, vals)

                seed_metrics.append({
                    "delta": delta,
                    "max_dev": max_dev_val,
                    "max_dev_gen": max_dev_gen,
                    "auc": auc,
                    "rho": rho,
                    "p": p_val,
                    "n_gens": len(gens),
                })

            if not seed_metrics:
                continue

            def agg(key):
                arr = [m[key] for m in seed_metrics if not (isinstance(m[key], float) and np.isnan(m[key]))]
                if not arr:
                    return None, None
                return round(np.mean(arr), 6), round(np.std(arr, ddof=0), 6) if len(arr) > 1 else 0.0

            mean_delta, std_delta = agg("delta")
            mean_max_dev, std_max_dev = agg("max_dev")
            mean_auc, std_auc = agg("auc")
            mean_rho, std_rho = agg("rho")

            dn = sig_name(sig)
            entry = {
                "metric_level": "auxiliary",
                "novelty": get_novelty(dn),
                "n_seeds": len(seed_metrics),
                "n_gens": seed_metrics[0]["n_gens"],
                "gen0_to_genN_delta": {"mean": mean_delta, "std": std_delta},
                "max_deviation": {"mean": mean_max_dev, "std": std_max_dev},
                "cumulative_AUC": {"mean": mean_auc, "std": std_auc},
            }
            if mean_rho is not None:
                entry["monotonicity_rho"] = {"mean": round(mean_rho, 4), "std": round(std_rho, 4)}

            max_dev_gens = [m["max_dev_gen"] for m in seed_metrics]
            entry["max_deviation_gen"] = max_dev_gens if len(max_dev_gens) > 1 else max_dev_gens[0]

            entry["per_seed"] = {}
            for i, seed in enumerate(seeds):
                if i < len(seed_metrics):
                    m = seed_metrics[i]
                    entry["per_seed"][str(seed)] = {
                        "delta": round(m["delta"], 6),
                        "max_dev": round(m["max_dev"], 6),
                        "auc": round(m["auc"], 6),
                        "rho": round(m["rho"], 4) if not np.isnan(m["rho"]) else None,
                    }

            frac_results[dn] = entry
        results[f"frac_{frac_label}pct"] = frac_results
    return results


def cross_fraction_spearman(table, seeds, fracs, signals):
    results = {}
    frac_values = [float(f) for f in fracs]
    max_gen = max(gen for (_, _, gen) in table.keys()) + 1
    for gen in range(max_gen):
        gen_results = {}
        for sig in signals:
            rhos = []
            for seed in seeds:
                fvals = []
                svals = []
                for frac_label, fv in zip(fracs, frac_values):
                    key = (seed, frac_label, gen)
                    if key in table and sig in table[key]:
                        fvals.append(fv)
                        svals.append(table[key][sig])
                if len(fvals) >= 3:
                    rho, p = stats.spearmanr(fvals, svals)
                    rhos.append({"rho": rho, "p": p, "n": len(fvals)})
            dn = sig_name(sig)
            if rhos:
                mean_rho = np.mean([r["rho"] for r in rhos])
                std_rho = np.std([r["rho"] for r in rhos], ddof=0) if len(rhos) > 1 else 0
                gen_results[dn] = {
                    "metric_level": "primary",
                    "novelty": get_novelty(dn),
                    "mean_rho": round(mean_rho, 4),
                    "std_rho": round(std_rho, 4),
                    "n_seeds": len(rhos),
                    "n_fracs": rhos[0]["n"],
                }
            elif len(frac_values) == 2:
                diffs = []
                for seed in seeds:
                    vals = {}
                    for frac_label in fracs:
                        key = (seed, frac_label, gen)
                        if key in table and sig in table[key]:
                            vals[frac_label] = table[key][sig]
                    if len(vals) == 2:
                        lo, hi = sorted(fracs, key=float)
                        diffs.append(vals[hi] - vals[lo])
                if diffs:
                    gen_results[dn] = {
                        "metric_level": "primary",
                        "novelty": get_novelty(dn),
                        "note": "only 2 fractions, showing diff (high-low)",
                        "mean_diff": round(np.mean(diffs), 6),
                        "std_diff": round(np.std(diffs, ddof=0), 6) if len(diffs) > 1 else 0,
                        "n_seeds": len(diffs),
                    }
        results[f"gen_{gen}"] = gen_results
    return results


def per_seed_stats(table, seeds, fracs, signals):
    results = {}
    for frac_label in fracs:
        frac_results = {}
        max_gen = 0
        for (s, f, g) in table.keys():
            if f == frac_label:
                max_gen = max(max_gen, g)
        for gen in range(max_gen + 1):
            gen_stats = {}
            for sig in signals:
                vals = []
                for seed in seeds:
                    key = (seed, frac_label, gen)
                    if key in table and sig in table[key]:
                        vals.append(table[key][sig])
                if vals:
                    gen_stats[sig_name(sig)] = {
                        "mean": round(np.mean(vals), 6),
                        "std": round(np.std(vals, ddof=0), 6) if len(vals) > 1 else 0,
                        "n": len(vals),
                    }
            frac_results[f"gen_{gen}"] = gen_stats
        results[f"frac_{frac_label}pct"] = frac_results
    return results


# ── Pretty-print ──

def print_ranking_table(xgen_results):
    for frac_key, frac_data in sorted(xgen_results.items()):
        frac_pct = frac_key.replace("frac_", "").replace("pct", "%")
        print(f"\n{'='*90}")
        print(f"  Severity Monitor Ranking — PubMed (frac={frac_pct}, auxiliary metrics)")
        print(f"{'='*90}")
        header = f"  {'Signal':<22} {'Novelty':<10} {'Delta(gN)':>10} {'MaxDev':>10} {'AUC':>10} {'Mono rho':>10}"
        print(header)
        print(f"  {'-'*72}")

        rows = []
        for sig, entry in frac_data.items():
            delta_m = entry["gen0_to_genN_delta"]["mean"]
            maxdev_m = entry["max_deviation"]["mean"]
            auc_m = entry["cumulative_AUC"]["mean"]
            rho_m = entry.get("monotonicity_rho", {}).get("mean", None)
            novelty = entry["novelty"]
            rows.append((sig, novelty, delta_m, maxdev_m, auc_m, rho_m))

        rows.sort(key=lambda r: abs(r[4]) if r[4] is not None else 0, reverse=True)

        for sig, novelty, delta, maxdev, auc, rho in rows:
            delta_s = f"{delta:+.4f}" if delta is not None else "N/A"
            maxdev_s = f"{maxdev:.4f}" if maxdev is not None else "N/A"
            auc_s = f"{auc:.4f}" if auc is not None else "N/A"
            rho_s = f"{rho:+.2f}" if rho is not None else "N/A"
            print(f"  {sig:<22} {novelty:<10} {delta_s:>10} {maxdev_s:>10} {auc_s:>10} {rho_s:>10}")


def print_table(title, data, col_width=14):
    print(f"\n{'='*80}")
    print(f"  {title}")
    print(f"{'='*80}")

    if not data:
        print("  (no data)")
        return

    for section_key, section_data in sorted(data.items()):
        print(f"\n  [{section_key}]")
        if not section_data:
            print("    (no data)")
            continue

        first_val = next(iter(section_data.values()))
        if isinstance(first_val, dict) and first_val:
            inner = next(iter(first_val.values()))
            if isinstance(inner, dict) and "mean" in inner:
                print_per_seed_section(section_key, section_data)
                continue

        sigs = list(section_data.keys())
        header = f"    {'signal':<22}"
        for field in ["mean_rho", "std_rho", "n_seeds", "mean_diff", "std_diff", "mean", "std", "n"]:
            if any(field in (section_data[s] if isinstance(section_data[s], dict) else {}) for s in sigs):
                header += f"{field:>{col_width}}"
        print(header)
        print(f"    {'-'*len(header)}")

        for sig in sigs:
            vals = section_data[sig]
            if isinstance(vals, dict):
                line = f"    {sig:<22}"
                for field in ["mean_rho", "std_rho", "n_seeds", "mean_diff", "std_diff", "mean", "std", "n"]:
                    if field in vals:
                        v = vals[field]
                        if isinstance(v, float):
                            line += f"{v:>{col_width}.4f}"
                        else:
                            line += f"{v:>{col_width}}"
                if "note" in vals:
                    line += f"  ({vals['note']})"
                print(line)


def print_per_seed_section(section_key, section_data):
    gens = sorted(section_data.keys())
    all_sigs = []
    for g in gens:
        for s in section_data[g]:
            if s not in all_sigs:
                all_sigs.append(s)
    cw = 18
    header = f"    {'signal':<22}" + "".join(f"{g:>{cw}}" for g in gens)
    print(header)
    print(f"    {'-'*(22 + cw * len(gens))}")
    for sig in all_sigs:
        line = f"    {sig:<22}"
        for g in gens:
            if sig in section_data[g]:
                m = section_data[g][sig]["mean"]
                s = section_data[g][sig]["std"]
                line += f"{m:>10.4f}+/-{s:<6.4f}"
            else:
                line += f"{'N/A':>{cw}}"
        print(line)


# ── Cross-domain comparison ──

def compare_domains(pubmed_output, wikitext_json_path):
    with open(wikitext_json_path) as f:
        wikitext = json.load(f)

    print(f"\n{'='*90}")
    print("  CROSS-DOMAIN COMPARISON: PubMed vs WikiText")
    print(f"{'='*90}")

    pm_xgen = pubmed_output.get("cross_generation_auxiliary", {})
    wt_xgen = wikitext.get("cross_generation_auxiliary", {})

    common_fracs = sorted(set(pm_xgen.keys()) & set(wt_xgen.keys()))
    if not common_fracs:
        print("  No overlapping fractions between PubMed and WikiText results.")
        return {}

    comparison = {}
    for frac_key in common_fracs:
        pm_data = pm_xgen[frac_key]
        wt_data = wt_xgen[frac_key]
        common_sigs = sorted(set(pm_data.keys()) & set(wt_data.keys()))

        if len(common_sigs) < 3:
            print(f"\n  [{frac_key}] Only {len(common_sigs)} common signals — skipping Spearman")
            comparison[frac_key] = {"n_common": len(common_sigs), "rank_rho": None}
            continue

        pm_auc = [pm_data[s]["cumulative_AUC"]["mean"] for s in common_sigs]
        wt_auc = [wt_data[s]["cumulative_AUC"]["mean"] for s in common_sigs]

        pm_rank = stats.rankdata([-abs(a) for a in pm_auc])
        wt_rank = stats.rankdata([-abs(a) for a in wt_auc])

        rho, p = stats.spearmanr(pm_rank, wt_rank)

        frac_pct = frac_key.replace("frac_", "").replace("pct", "%")
        print(f"\n  [{frac_pct}] Signal ranking comparison (by |AUC|, descending):")
        print(f"    {'Signal':<22} {'PM_AUC':>10} {'PM_Rank':>8} {'WT_AUC':>10} {'WT_Rank':>8}")
        print(f"    {'-'*58}")
        for i, sig in enumerate(common_sigs):
            print(f"    {sig:<22} {pm_auc[i]:>10.4f} {pm_rank[i]:>8.0f} {wt_auc[i]:>10.4f} {wt_rank[i]:>8.0f}")
        print(f"\n    Rank correlation (Spearman rho): {rho:+.4f}  (p={p:.4f})")

        if abs(rho) > 0.7:
            verdict = "CONSISTENT — signal rankings agree across domains"
        elif abs(rho) > 0.3:
            verdict = "PARTIAL — some ranking agreement"
        else:
            verdict = "DIVERGENT — domain-specific signal behavior"
        print(f"    Verdict: {verdict}")

        comparison[frac_key] = {
            "n_common": len(common_sigs),
            "signals": common_sigs,
            "pubmed_auc": {s: a for s, a in zip(common_sigs, pm_auc)},
            "wikitext_auc": {s: a for s, a in zip(common_sigs, wt_auc)},
            "rank_spearman_rho": round(rho, 4),
            "rank_spearman_p": round(p, 4),
            "verdict": verdict,
        }

    return comparison


def main():
    parser = argparse.ArgumentParser(description="PubMed v2 incremental analysis")
    parser.add_argument("--data-dir", type=str, required=True,
                        help="Base directory (e.g. /root/autodl-tmp/collapse_severity_monitor)")
    parser.add_argument("--seeds", type=int, nargs="+", default=[42],
                        help="Seeds to include (default: 42)")
    parser.add_argument("--output", type=str, default=None,
                        help="Output JSON path (default: <data-dir>/analysis_pubmed_v2.json)")
    parser.add_argument("--compare-wikitext", type=str, default=None,
                        help="Path to WikiText v2 analysis JSON for cross-domain comparison")
    args = parser.parse_args()

    base_dir = args.data_dir
    seeds = args.seeds

    if not os.path.isdir(base_dir):
        print(f"ERROR: {base_dir} does not exist")
        sys.exit(1)

    fracs = discover_fractions(base_dir, seeds)
    if not fracs:
        print(f"ERROR: No PubMed data found for seeds {seeds}")
        print(f"  Expected: {output_dir_pattern(base_dir).format(seed='<seed>')}/summary_*pct.json")
        sys.exit(1)

    print(f"Domain: PubMed")
    print(f"Seeds: {seeds}")
    print(f"Fractions: {fracs}")

    table = build_data_table(base_dir, seeds, fracs)
    signals = available_signals(table)

    print(f"Available signals: {[sig_name(s) for s in signals]}")
    print(f"Total data points: {len(table)}")

    xgen = cross_generation_analysis(table, seeds, fracs, signals)
    print_ranking_table(xgen)

    xfrac = cross_fraction_spearman(table, seeds, fracs, signals)
    print_table("Cross-Fraction Analysis — PubMed (signal vs fraction) [PRIMARY]", xfrac)

    pstats = per_seed_stats(table, seeds, fracs, signals)
    print_table("Per-Seed Statistics — PubMed (mean +/- std across seeds)", pstats)

    output = {
        "analysis_version": "v2",
        "domain": "pubmed",
        "metric_hierarchy": {
            "primary": "Cross-fraction Spearman rho (requires >= 3 fractions)",
            "auxiliary": "Cross-generation metrics: gen0_to_genN_delta, max_deviation, cumulative_AUC, monotonicity_rho",
        },
        "seeds": seeds,
        "fractions": fracs,
        "n_seeds": len(seeds),
        "signals": [sig_name(s) for s in signals],
        "cross_generation_auxiliary": xgen,
        "cross_fraction_primary": xfrac,
        "per_seed_stats": pstats,
    }

    cross_domain = None
    if args.compare_wikitext:
        if not os.path.exists(args.compare_wikitext):
            print(f"\nWARNING: WikiText JSON not found at {args.compare_wikitext}, skipping comparison")
        else:
            cross_domain = compare_domains(output, args.compare_wikitext)
            output["cross_domain_comparison"] = cross_domain

    out_path = args.output
    if not out_path:
        out_path = os.path.join(base_dir, "analysis_pubmed_v2.json")
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nJSON saved to: {out_path}")


if __name__ == "__main__":
    main()
